                Node n = neo4jGraph.findNodesByLabelAndProperty(NODE_LABEL, NODE_ID, String.valueOf(nodeId)).iterator()
                    .next();
                for (Relationship relationship : n.getRelationships(RelTypes.SIMILAR, Direction.OUTGOING))
